<template>
  <section class="page report-page" v-loading="loading">
    <header class="page-header"><div><span class="eyebrow">REPORTS & ARCHIVES</span><h1>报告与归档</h1><p>统一管理正式安全研判报告、实验快照和可追溯证据。</p></div><div class="header-actions"><el-button :icon="Refresh" @click="load">刷新</el-button></div></header>
    <el-alert v-if="loadError" :title="loadError" type="error" show-icon :closable="false" />

    <el-tabs v-model="activeTab" class="workspace-tabs report-tabs">
      <el-tab-pane label="报告中心" name="reports">
        <section class="operation-section">
          <div class="section-head"><div><h2>安全研判报告</h2><p>报告预览、Markdown、JSON 与页面数据使用同一当前汇总接口。</p></div></div>
          <DataTable :rows="reportRows">
            <el-table-column label="报告编号" min-width="210"><template #default="{ row }"><strong class="mono">{{ row.report_no }}</strong><small class="cell-sub">{{ row.name }}</small></template></el-table-column>
            <el-table-column prop="experiment_no" label="实验 / 任务编号" min-width="190" /><el-table-column prop="assets" label="资产" width="80" align="right" /><el-table-column prop="vulnerabilities" label="漏洞" width="80" align="right" /><el-table-column prop="high_risks" label="高风险" width="90" align="right" />
            <el-table-column label="审计状态" width="120"><template #default="{ row }"><span class="status-label" :class="row.auditClass">{{ row.audit }}</span></template></el-table-column>
            <el-table-column label="生成时间" min-width="170"><template #default="{ row }"><span class="mono cell-time">{{ formatTime(row.generated_at) }}</span></template></el-table-column>
            <el-table-column label="操作" width="170" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="preview(row)">{{ row.current ? '正式预览' : '查看归档 JSON' }}</el-button><a v-if="row.filename" class="text-link" :href="archiveDownloadUrl(row.filename)">下载</a></template></el-table-column>
          </DataTable>
        </section>
      </el-tab-pane>
      <el-tab-pane label="实验归档" name="archives">
        <section class="operation-section"><div class="section-head"><div><h2>实验快照</h2><p>保留资产、漏洞、风险、处置任务和运行时事件的历史快照。</p></div></div>
          <DataTable :rows="archives"><el-table-column prop="filename" label="实验编号" min-width="220" /><el-table-column label="资产" width="80"><template #default="{ row }">{{ row.summary?.assets || 0 }}</template></el-table-column><el-table-column label="漏洞" width="80"><template #default="{ row }">{{ row.summary?.vulnerabilities || 0 }}</template></el-table-column><el-table-column label="风险" width="80"><template #default="{ row }">{{ row.summary?.risks || 0 }}</template></el-table-column><el-table-column label="处置" width="80"><template #default="{ row }">{{ row.summary?.tasks || 0 }}</template></el-table-column><el-table-column label="证据事件" width="100"><template #default="{ row }">{{ row.summary?.events || 0 }}</template></el-table-column><el-table-column label="归档时间" min-width="175"><template #default="{ row }"><span class="mono cell-time">{{ formatTime(row.archived_at) }}</span></template></el-table-column><el-table-column label="大小" width="100"><template #default="{ row }">{{ formatBytes(row.size_bytes) }}</template></el-table-column><el-table-column label="操作" width="140"><template #default="{ row }"><a class="text-link" :href="archiveViewUrl(row.filename)" target="_blank">查看 JSON</a><a class="text-link" :href="archiveDownloadUrl(row.filename)">下载</a></template></el-table-column></DataTable>
        </section>
      </el-tab-pane>
    </el-tabs>

    <section v-if="previewOpen" ref="reportPaper" class="report-paper">
      <header class="report-cover"><div class="report-classification">LINUX VULNERABILITY SECURITY ASSESSMENT</div><h1>Linux 漏洞风险研判与修复决策报告</h1><p>基于资产适用性、外部情报、运行时证据和审计策略形成的正式研判记录</p><dl><div><dt>报告编号</dt><dd>{{ selectedReport.report_no }}</dd></div><div><dt>任务 / 实验编号</dt><dd>{{ selectedReport.experiment_no }}</dd></div><div><dt>生成时间</dt><dd>{{ formatTime(selectedReport.generated_at) }}</dd></div><div><dt>审计状态</dt><dd><span :class="['report-risk', selectedReport.auditClass]">{{ selectedReport.audit }}</span></dd></div></dl></header>

      <section class="paper-section"><h2>1. 执行摘要</h2><p>{{ executiveSummary }}</p><div class="summary-callout"><strong>优先处置建议</strong><span>{{ priorityAdvice }}</span></div></section>
      <section class="paper-section"><h2>2. 风险总览</h2><table class="paper-table summary-table"><thead><tr><th>资产</th><th>漏洞情报</th><th>有效命中</th><th>高风险</th><th>KEV</th><th>待人工审核</th></tr></thead><tbody><tr><td>{{ report.overview?.asset_count || 0 }}</td><td>{{ report.overview?.vulnerability_count || 0 }}</td><td>{{ report.overview?.affected_match_count || 0 }}</td><td>{{ highRiskCount }}</td><td>{{ kevCount }}</td><td>{{ report.overview?.human_review_required_count || 0 }}</td></tr></tbody></table></section>
      <section class="paper-section"><h2>3. 高风险漏洞清单</h2><table class="paper-table"><thead><tr><th>序号</th><th>CVE</th><th>资产</th><th>风险</th><th>CVSS</th><th>EPSS</th><th>KEV</th><th>审核状态</th></tr></thead><tbody><tr v-for="risk in topRisks" :key="`${risk.asset_id}-${risk.cve_id}`"><td>{{ risk.rank }}</td><td>{{ risk.cve_id }}</td><td>{{ risk.hostname || assetName(risk.asset_id) }}</td><td><span :class="['report-risk', riskClass(effectiveRiskLevel(risk))]">{{ effectiveRiskLevel(risk) }}</span></td><td>{{ risk.risk_factors?.technical_severity?.cvss_score ?? "—" }}</td><td>{{ percent(risk.risk_factors?.exploit_likelihood?.probability) }}</td><td>{{ risk.risk_factors?.known_exploitation?.is_kev ? "是" : "否" }}</td><td>{{ reviewLabel(risk.review_status) }}</td></tr><tr v-if="!topRisks.length"><td colspan="8" class="paper-empty">暂无高风险记录</td></tr></tbody></table></section>
      <section class="paper-section"><div class="paper-heading-row"><h2>4. 单漏洞完整研判</h2><el-select v-if="topRisks.length" v-model="selectedRiskKey" size="small"><el-option v-for="risk in topRisks" :key="`${risk.asset_id}-${risk.cve_id}`" :label="`${risk.cve_id} / ${assetName(risk.asset_id)}`" :value="`${risk.asset_id}-${risk.cve_id}`" /></el-select></div>
        <template v-if="selectedRisk"><h3>4.1 CVE 基础信息与多源情报</h3><table class="paper-table detail-table"><tbody><tr><th>CVE</th><td>{{ selectedRisk.cve_id }}</td><th>资产</th><td>{{ assetName(selectedRisk.asset_id) }}</td></tr><tr><th>Canonical</th><td>{{ sourceValue("canonical", "status") }} / {{ sourceValue("canonical", "release") }}</td><th>软件包与修复版本</th><td>{{ sourceValue("canonical", "package") }} / {{ sourceValue("canonical", "fixed_version") }}</td></tr><tr><th>NVD</th><td>CVSS {{ selectedRisk.risk_factors?.technical_severity?.cvss_score ?? "—" }}</td><th>CISA KEV</th><td>{{ selectedRisk.risk_factors?.known_exploitation?.is_kev ? "已收录" : "未收录" }}</td></tr><tr><th>FIRST EPSS</th><td>{{ percent(selectedRisk.risk_factors?.exploit_likelihood?.probability) }}</td><th>Ubuntu 适用性</th><td>{{ selectedRisk.risk_factors?.ubuntu_applicability?.status || "未知" }}</td></tr></tbody></table>
          <h3>4.2 资产命中与版本证据</h3><p class="paper-evidence">{{ selectedChain?.matching?.reason || "当前报告未返回更细的版本命中说明。" }}</p>
          <h3>4.3 运行时证据</h3><table class="paper-table detail-table"><tbody><tr><th>验证状态</th><td>{{ selectedChain?.runtime_verification?.status || selectedRisk.risk_factors?.environment?.runtime_status || "未知" }}</td><th>证据强度</th><td>{{ selectedChain?.runtime_verification?.strength ?? "—" }}</td></tr><tr><th>服务暴露</th><td>{{ selectedRisk.risk_factors?.environment?.reachable_status || "未知" }}</td><th>结论</th><td>{{ selectedChain?.runtime_verification?.conclusion || "暂无详细运行时结论" }}</td></tr></tbody></table>
          <h3>4.4 专业研判、复议与裁决</h3><p class="paper-evidence">{{ selectedRisk.reason || selectedRisk.review_reason || "尚未形成专业研判结论。" }}</p><table class="paper-table detail-table"><tbody><tr><th>研判结论</th><td>{{ selectedRisk.review_verdict || "待研判" }}</td><th>置信度</th><td>{{ percent(selectedRisk.review_confidence) }}</td></tr><tr><th>冲突复议</th><td>{{ (selectedRisk.review_conflicts || []).join("；") || "未记录冲突" }}</td><th>最终裁决</th><td>{{ selectedRisk.has_final_conclusion ? `${selectedRisk.risk_level} / ${selectedRisk.final_score}` : "待人工审核确认" }}</td></tr></tbody></table>
          <h3>4.5 修复建议与人工审计</h3><table class="paper-table detail-table"><tbody><tr><th>修复建议</th><td>{{ selectedChain?.remediation?.command || selectedRisk.recommended_action || "待审计后生成" }}</td><th>人工审核</th><td>{{ selectedRisk.human_review_required ? "必须人工审核" : "策略允许自动确认" }}</td></tr><tr><th>审核原因</th><td colspan="3">{{ (selectedRisk.audit_policy_reasons || []).join("；") || selectedRisk.decision_reason || "未返回附加审核原因" }}</td></tr></tbody></table>
        </template><p v-else class="paper-empty">没有可用于完整研判展示的风险对象。</p>
      </section>
      <section class="paper-section"><h2>5. 修复与处置建议</h2><ol class="recommendations"><li>优先处理已确认命中、对外暴露或存在 KEV 记录的风险对象。</li><li>有固定版本时执行 Root-Fixed 升级；无固定版本时先采用 Surface-Fixed 降低暴露面。</li><li>处置完成后重新采集软件包、服务与运行时证据，并重新计算风险。</li></ol></section>
      <section class="paper-section"><h2>6. 审计记录</h2><table class="paper-table detail-table"><tbody><tr><th>研判批次</th><td>{{ report.review?.status || "未执行" }}</td><th>人工审核对象</th><td>{{ report.overview?.human_review_required_count || 0 }}</td></tr><tr><th>整体结论</th><td colspan="3">{{ report.review?.verdict || "暂无批次结论" }}</td></tr></tbody></table></section>
      <section class="paper-section"><h2>7. 情报来源与更新时间</h2><table class="paper-table"><thead><tr><th>来源</th><th>职责</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="source in sourceRows" :key="source.key"><td>{{ source.name }}</td><td>{{ source.role }}</td><td>{{ source.status }}</td><td>{{ formatTime(source.updated) }}</td></tr></tbody></table></section>
      <footer class="report-footer"><span>LinuxGuard · Linux 漏洞风险研判与修复决策平台</span><span>{{ selectedReport.report_no }}</span></footer>
    </section>

    <div v-if="previewOpen" class="preview-actions"><a class="el-button" :href="currentReportUrls.markdown">下载 Markdown</a><a class="el-button" :href="currentReportUrls.json">下载 JSON</a><a class="el-button" :href="currentReportUrls.csv">下载 CSV</a><el-button type="primary" @click="printReport">打印 / 保存 PDF</el-button><el-button @click="previewOpen = false">关闭预览</el-button></div>
  </section>
</template>

<script setup>
import { Refresh } from "@element-plus/icons-vue";
import { computed, nextTick, onMounted, ref } from "vue";
import DataTable from "../components/DataTable.vue";
import { archiveDownloadUrl, archiveViewUrl, currentReportUrls, fetchAssets, fetchBehaviorChains, fetchReportArchives, fetchReportJson } from "../api";

const loading = ref(false); const loadError = ref(""); const report = ref({}); const archives = ref([]); const assets = ref([]); const chains = ref([]); const activeTab = ref("reports"); const previewOpen = ref(false); const selectedReport = ref({}); const selectedRiskKey = ref(""); const reportPaper = ref(null);
const topRisks = computed(() => report.value.top_risks || []);
const highRiskCount = computed(() => Number(report.value.overview?.high_risk_count ?? topRisks.value.filter((x) => ["Critical", "High"].includes(effectiveRiskLevel(x))).length));
const kevCount = computed(() => Number(report.value.overview?.kev_vulnerability_count ?? topRisks.value.filter((x) => x.risk_factors?.known_exploitation?.is_kev).length));
const currentNumber = computed(() => `LG-${new Date().toISOString().slice(0, 10).replaceAll("-", "")}-CURRENT`);
const reportRows = computed(() => [{ report_no: currentNumber.value, experiment_no: "当前有效数据集", name: "Linux 漏洞风险研判报告", assets: report.value.overview?.asset_count || 0, vulnerabilities: report.value.overview?.vulnerability_count || 0, high_risks: highRiskCount.value, audit: report.value.overview?.human_review_required_count ? "待人工审核" : "审计通过", auditClass: report.value.overview?.human_review_required_count ? "is-high" : "approved", generated_at: new Date().toISOString(), current: true }, ...archives.value.filter((x) => Number(x.summary?.vulnerabilities || x.summary?.risks) > 0).slice(0, 12).map((x) => ({ report_no: x.filename.replace(".json", "").toUpperCase(), experiment_no: x.filename.replace(".json", ""), name: "历史实验归档", assets: x.summary?.assets || 0, vulnerabilities: x.summary?.vulnerabilities || 0, high_risks: x.summary?.high_risks ?? "—", audit: "已归档", auditClass: "approved", generated_at: x.archived_at, filename: x.filename }))]);
const selectedRisk = computed(() => topRisks.value.find((x) => `${x.asset_id}-${x.cve_id}` === selectedRiskKey.value) || topRisks.value[0] || null);
const selectedChain = computed(() => chains.value.find((x) => Number(x.asset?.id) === Number(selectedRisk.value?.asset_id) && x.intelligence?.cve_id === selectedRisk.value?.cve_id) || null);
const executiveSummary = computed(() => `本次评估覆盖 ${report.value.overview?.asset_count || 0} 台 Linux 资产、${report.value.overview?.vulnerability_count || 0} 条漏洞情报，确认 ${report.value.overview?.affected_match_count || 0} 条资产命中。当前识别 ${highRiskCount.value} 条高风险对象、${kevCount.value} 条 KEV 相关对象，${report.value.overview?.human_review_required_count || 0} 条对象仍需人工审核。`);
const priorityAdvice = computed(() => topRisks.value[0] ? `优先核查 ${topRisks.value[0].cve_id} 在 ${assetName(topRisks.value[0].asset_id)} 上的适用性、暴露路径和修复版本。` : "当前没有进入优先处置清单的风险对象。" );
const sourceRows = computed(() => { const sourceData = selectedRisk.value?.intelligence_sources || {}; return [{ key: "canonical", name: "Canonical Ubuntu", role: "Ubuntu 与软件包适用性" }, { key: "nvd", name: "NVD", role: "技术严重度与 CWE" }, { key: "cisa_kev", name: "CISA KEV", role: "已知在野利用" }, { key: "epss", name: "FIRST EPSS", role: "利用概率与百分位" }].map((x) => ({ ...x, status: sourceData[x.key]?.status || "未返回", updated: sourceData[x.key]?.source_updated_at || sourceData[x.key]?.fetched_at })); });
const assetName = (id) => assets.value.find((x) => Number(x.id) === Number(id))?.hostname || `资产 ${id}`;
const formatTime = (value) => value ? new Date(value).toLocaleString("zh-CN", { hour12: false }) : "未知";
const formatBytes = (value) => value ? `${(Number(value) / 1024 / 1024).toFixed(1)} MB` : "—";
const percent = (value) => value === null || value === undefined ? "—" : `${(Number(value) * 100).toFixed(2)}%`;
const effectiveRiskLevel = (risk) => risk?.has_final_conclusion ? (risk.risk_level || "待定") : (risk?.preliminary_level || "待定");
const riskClass = (value) => ({ Critical: "is-critical", High: "is-high", Medium: "is-medium", Low: "is-low" }[value] || "is-muted");
const reviewLabel = (value) => ({ pending_human_review: "待人工审核", auto_confirmed: "自动确认", human_confirmed: "人工确认", candidate: "待研判" }[value] || value || "未研判");
const sourceValue = (source, key) => selectedRisk.value?.intelligence_sources?.[source]?.value?.[key] || "—";
const load = async () => { loading.value = true; loadError.value = ""; try { const [r, a, assetRows, chainRows] = await Promise.all([fetchReportJson(), fetchReportArchives(), fetchAssets(), fetchBehaviorChains().catch(() => [])]); report.value = r || {}; archives.value = Array.isArray(a) ? a : (a.archives || []); assets.value = assetRows || []; chains.value = chainRows || []; if (topRisks.value[0]) selectedRiskKey.value = `${topRisks.value[0].asset_id}-${topRisks.value[0].cve_id}`; } catch (error) { loadError.value = error?.response?.data?.detail || error?.message || "报告数据加载失败"; } finally { loading.value = false; } };
const preview = async (row) => { if (row.filename) { window.open(archiveViewUrl(row.filename), "_blank", "noopener"); return; } selectedReport.value = row; previewOpen.value = true; await nextTick(); reportPaper.value?.scrollIntoView({ behavior: "smooth", block: "start" }); };
const printReport = () => window.print();
onMounted(load);
</script>

<style scoped>
.report-tabs { min-width: 0; }.cell-time { color: var(--soc-text-muted); font-size: 10px; }.text-link { margin-left: 10px; color: var(--el-color-primary); font-size: 12px; text-decoration: none; }.report-paper { width: min(1120px, 100%); margin: 10px auto 0; border: 1px solid #c8cdd3; background: #fff; color: #1d2732; box-shadow: 0 12px 30px rgba(0,0,0,.22); }.report-cover { padding: 58px 62px 42px; border-top: 8px solid #26394f; border-bottom: 1px solid #8d98a4; }.report-classification { color: #5e6c7b; font: 600 11px Consolas, monospace; letter-spacing: .16em; }.report-cover h1 { margin: 30px 0 10px; color: #172333; font-size: 30px; font-weight: 620; }.report-cover > p { margin: 0 0 38px; color: #586575; }.report-cover dl { display: grid; grid-template-columns: repeat(2, 1fr); margin: 0; border-top: 1px solid #aeb6bf; border-left: 1px solid #aeb6bf; }.report-cover dl div { display: grid; grid-template-columns: 125px 1fr; padding: 10px 12px; border-right: 1px solid #aeb6bf; border-bottom: 1px solid #aeb6bf; }.report-cover dt { color: #687482; }.report-cover dd { color: #1d2732; font-family: Consolas, monospace; }.paper-section { padding: 30px 62px 4px; }.paper-section h2 { margin: 0 0 16px; padding-bottom: 8px; border-bottom: 2px solid #2f4359; color: #1e2d3e; font-size: 18px; }.paper-section h3 { margin: 22px 0 10px; color: #35485c; font-size: 14px; }.paper-section p { color: #394655; line-height: 1.8; }.summary-callout { display: grid; grid-template-columns: 130px 1fr; gap: 16px; padding: 13px 15px; border-left: 4px solid #b96a33; background: #f4f1ed; }.paper-table { width: 100%; border-collapse: collapse; font-size: 12px; }.paper-table th, .paper-table td { padding: 9px 10px; border: 1px solid #b9c0c8; text-align: left; vertical-align: top; }.paper-table th { background: #edf0f3; color: #435162; font-weight: 600; }.summary-table td { color: #1b2a3a; font: 600 20px Consolas, monospace; text-align: center; }.detail-table th { width: 145px; }.paper-risk, .report-risk { display: inline-block; padding: 2px 6px; border: 1px solid #8893a0; font-size: 10px; }.report-risk.is-critical { border-color: #a64040; color: #962f2f; }.report-risk.is-high { border-color: #b86b36; color: #a65120; }.report-risk.is-medium { border-color: #ae8a2f; color: #806510; }.report-risk.approved { border-color: #4c8968; color: #347354; }.paper-heading-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; border-bottom: 2px solid #2f4359; }.paper-heading-row h2 { flex: 1; border-bottom: 0; }.paper-evidence { padding: 12px 14px; border-left: 3px solid #657b92; background: #f3f5f7; }.paper-empty { padding: 20px !important; color: #758190; text-align: center !important; }.recommendations { padding-left: 22px; color: #394655; line-height: 1.9; }.report-footer { display: flex; justify-content: space-between; margin-top: 34px; padding: 18px 62px; border-top: 1px solid #aeb6bf; color: #697686; font-size: 10px; }.preview-actions { position: sticky; bottom: 12px; z-index: 5; display: flex; justify-content: center; gap: 8px; padding: 10px; }.preview-actions a { display: inline-flex; align-items: center; text-decoration: none; }
@media (max-width: 760px) { .report-cover, .paper-section { padding-left: 22px; padding-right: 22px; }.report-cover dl { grid-template-columns: 1fr; }.paper-table { min-width: 700px; }.paper-section { overflow-x: auto; } }
@media print { :global(.sidebar), :global(.topbar), .page-header, .report-tabs, .preview-actions, .el-alert { display: none !important; }.report-paper { width: 100%; margin: 0; border: 0; box-shadow: none; }.report-page { display: block; } }
</style>
